select p.id as problem_id, pv.version_no, pv.options, pv.correct_index, (select count(*) from problem_versions v where v.problem_id = p.id and v.status in ('draft', 'in_review')) as inflight_versions,
  (select string_agg(distinct s.name || ' (' || s.status || ')', ', ') from mock_exam_set_items i join mock_exam_sets s on s.id = i.exam_set_id where i.problem_id = p.id and s.status in ('published', 'draft')) as used_in
from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['05fcc748-6621-41c8-871c-a1bd9ac131eb','457a2e9f-02ef-41d4-b1d3-a6f1e6e6d90d','508b24dd-fe8e-43c6-b165-408aac130a64','67cf630d-3d76-4c4f-92a7-d397cdce8eb0','813a21dd-752b-40fb-9027-e85e7dc19812','92fa817c-dbaf-4b0c-abd0-011e93f2cc76','a129f183-7cb5-4697-95fa-ce3215fb9761']::uuid[]) order by p.id;
